#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker was a raw pointer member with no UPROPERTY() macro, so the garbage collector did not see the reference. The NewObject-created ScoreTracker was unreachable and got purged by GC (log: 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13). The next goal (~1 minute later) dereferenced the dangling pointer in OnGoalScored -> UArenaScoreTracker::AddPoints, causing the EXCEPTION_ACCESS_VIOLATION fatal error. Fixed by adding UPROPERTY() TObjectPtr<> to ScoreTracker in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is loaded by hardcoded string path (LoadObject) instead of a cooked reference, and Config/DefaultGame.ini only forced cooking of /Game/Data/Effects, not /Game/Data/Palettes. With bCookAll=False the uncookable-by-reference asset was not packaged, so the packaged build logged 'Couldn't find file for package /Game/Data/Palettes/DA_Primary', Palette stayed null, and the HUD fell back to gray ('Palette is null, using fallback gray'). Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to DefaultGame.ini."
}
